package com.orient.ortts.demo;
import android.app.*;import android.os.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;

/** Fixed recorded-input release checks. Not a live microphone or quality benchmark. */
public final class AsrReleaseQaActivity extends Activity {
 private volatile StreamingPlayer player;private TextView view;private int requests;
 private long now(){return SystemClock.elapsedRealtimeNanos();}
 private void save(File f,JSONObject value)throws Exception{Files.write(f.toPath(),value.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 private float[] pcm(JSONObject f)throws Exception{String id=f.getString("id");if(!id.matches("[a-zA-Z0-9_-]+"))throw new IOException("fixture id");byte[] b=Files.readAllBytes(new File(getFilesDir(),"asr-fixtures/"+id+".f32").toPath());if(b.length==0||b.length%4!=0||b.length>16000*60*4)throw new IOException("fixture length");float[] p=new float[b.length/4];ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer().get(p);return p;}
 private JSONObject trial(JSONObject f)throws Exception{if(++requests>15)throw new IOException("QA request bound");SpeechBridge.resetAsr();float[] p=pcm(f);String[] text={""};int[] finals={0},partials={0};long start=now();for(int i=0;i<p.length;i+=3200){float[] chunk=Arrays.copyOfRange(p,i,Math.min(i+3200,p.length));SpeechBridge.accept(chunk,chunk.length,(t,e,s)->{if(e==0)partials[0]++;else{finals[0]++;text[0]=t;}});}SpeechBridge.finish((t,e,s)->{if(e==0)partials[0]++;else{finals[0]++;text[0]=t;}});return new JSONObject().put("id",f.getString("id")).put("text",text[0]).put("api_ms",(now()-start)/1e6).put("audio_s",p.length/16000.0).put("partial_events",partials[0]).put("final_events",finals[0]);}
 public void onCreate(Bundle b){super.onCreate(b);view=new TextView(this);view.setText("ASR release checks");setContentView(view);String id=getIntent().getStringExtra("qa_id");if(!BuildConfig.DEBUG||!getPackageName().endsWith(".qa")||id==null||!id.matches("[a-zA-Z0-9_-]{1,64}")||!MainActivity.busy.compareAndSet(false,true))return;getWindow().addFlags(128);MainActivity.worker.execute(()->run(id));}
 private void run(String id){File dir=new File(getFilesDir(),"asr-release-qa/"+id);dir.mkdirs();JSONObject result=new JSONObject();JSONArray steps=new JSONArray();String root=new File(getFilesDir(),"speech-models/Qwen3-ASR-0.6B-int8").getPath();try{
  SpeechBridge.load();result.put("capabilities",new JSONObject(SpeechBridge.capabilities())).put("recorded_input_not_live_microphone",true).put("model_root",root);
  JSONArray fs=new JSONObject(new String(Files.readAllBytes(new File(getFilesDir(),"asr-fixtures/FIXTURES.json").toPath()),java.nio.charset.StandardCharsets.UTF_8)).getJSONArray("trials");int[] indices={0,20,40};String[] control=new String[3];
  for(String profile:new String[]{"original-int8","headslice-compat"}){
   SpeechBridge.close();long start=now();SpeechBridge.openAsrProfile("qwen3_asr",root,profile);steps.put(new JSONObject().put("step","load").put("profile",profile).put("load_ms",(now()-start)/1e6));
   for(int i=0;i<indices.length;i++){JSONObject row=trial(fs.getJSONObject(indices[i]));if(row.getInt("partial_events")!=0||row.getInt("final_events")!=1)throw new IOException("Qwen must emit one offline final, no partial");if(profile.equals("original-int8"))control[i]=row.getString("text");else if(!control[i].equals(row.getString("text")))throw new IOException("original/head-slice transcript mismatch");row.put("profile",profile).put("original_headslice_exact",profile.equals("headslice-compat"));steps.put(row);}
  }
  SpeechBridge.close();boolean rejected=false;try{SpeechBridge.openAsrProfile("qwen3_asr",root,"compact");}catch(Exception e){rejected=true;steps.put(new JSONObject().put("step","unsupported_profile_rejected").put("error",e.toString()));}if(!rejected)throw new IOException("compact profile accepted");
  File invalid=new File(getFilesDir(),"asr-release-empty");invalid.mkdirs();rejected=false;try{SpeechBridge.openAsr("qwen3_asr",invalid.getPath());}catch(Exception e){rejected=true;steps.put(new JSONObject().put("step","missing_model_rejected").put("error",e.toString()));}if(!rejected)throw new IOException("bad model accepted");
  SpeechBridge.close();SpeechBridge.openAsr("qwen3_asr",root);SpeechBridge.resetAsr();float[] p=pcm(fs.getJSONObject(0));for(int n=0;n<p.length;n+=3200){float[] c=Arrays.copyOfRange(p,n,Math.min(n+3200,p.length));SpeechBridge.accept(c,c.length,(t,e,s)->{});}requests++;Thread cancel=new Thread(()->{SystemClock.sleep(20);SpeechBridge.cancel();});cancel.start();String error="";try{SpeechBridge.finish((t,e,s)->{});}catch(Exception e){error=e.toString();}finally{cancel.join();}if(!error.toLowerCase(Locale.ROOT).contains("cancel"))throw new IOException("Qwen cancellation not observed: "+error);steps.put(new JSONObject().put("step","cancel_after_compute").put("error",error));
  if(!control[0].equals(trial(fs.getJSONObject(0)).getString("text")))throw new IOException("cancel/reset changed output");
  SpeechBridge.close();SpeechBridge.openAsr("qwen3_asr",root);if(!control[0].equals(trial(fs.getJSONObject(0)).getString("text")))throw new IOException("release/reload changed output");steps.put(new JSONObject().put("step","reset_release_reload").put("exact",true));SpeechBridge.close();
  ModelManager manager=new ModelManager(this,s->{});File tts=manager.current();if(tts==null||!manager.ready("P3"))throw new IOException("Existing P3 cache required; no download");String spoken=control[0];if(spoken.trim().isEmpty())throw new IOException("Empty recognized text");
  File stopped=new File(dir,"tts-cancelled");stopped.mkdirs();boolean[] callback={false};String stoppedError="";requests++;try(StreamingPlayer stream=new StreamingPlayer(true,spoken.length())){player=stream;try{NativeBridge.run(tts.getPath(),"P3","female",spoken,4,20261029L,true,(x,r)->{callback[0]=true;stream.requestStop();stream.onPcm(x,r);},stopped.getPath(),ModelManager.acousticIdentity(tts));}catch(Exception e){stoppedError=e.toString();}}finally{player=null;}if(!callback[0]||stoppedError.isEmpty())throw new IOException("TTS cancel not observed");steps.put(new JSONObject().put("step","tts_cancel").put("error",stoppedError));
  File recovered=new File(dir,"tts-recovered");recovered.mkdirs();requests++;try(StreamingPlayer stream=new StreamingPlayer(true,spoken.length())){player=stream;JSONObject report=new JSONObject(NativeBridge.run(tts.getPath(),"P3","female",spoken,4,20261029L,true,stream,recovered.getPath(),ModelManager.acousticIdentity(tts)));stream.drain();report.put("playback",stream.metrics());if(!"eos".equals(report.getString("EOS"))||!report.getBoolean("callback_concat_exact"))throw new IOException("TTS recovery EOS/PCM mismatch");save(new File(dir,"TTS.json"),report);steps.put(new JSONObject().put("step","ASR_to_TTS_recovery").put("report",report));}finally{player=null;}
  NativeBridge.release();SpeechBridge.openAsr("qwen3_asr",root);if(!control[0].equals(trial(fs.getJSONObject(0)).getString("text")))throw new IOException("TTS to Qwen output mismatch");SpeechBridge.close();
  SpeechBridge.openAsr("sense_asr",new File(getFilesDir(),"speech-models/sensevoice-small-q8-audiocpp-v1.gguf").getPath());steps.put(trial(fs.getJSONObject(0)).put("profile","sense-existing"));SpeechBridge.close();
  result.put("ok",true);
 }catch(Throwable e){try{result.put("ok",false).put("error",e.toString());StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));result.put("trace",s.toString());}catch(Exception ignored){}}
 finally{try{SpeechBridge.close();NativeBridge.release();result.put("steps",steps).put("actual_requests",requests).put("human_quality","PENDING");save(new File(dir,"RESULT.json"),result);}catch(Exception ignored){}MainActivity.busy.set(false);runOnUiThread(()->view.setText(result.toString()));}}
 protected void onDestroy(){StreamingPlayer p=player;if(p!=null)p.requestStop();try{SpeechBridge.cancel();}catch(Throwable ignored){}super.onDestroy();}
}
